import{z as p,x as E,o as l,c as A,q as t,j as d,D as o,d as e,s,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Pollard rho","description":"","frontmatter":{"title":"Pollard rho","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pollard-rho.md","filePath":"cs/pollard-rho.md","lastUpdated":1791413859000}'),h={name:"cs/pollard-rho.md"};function B(c,a,x,m,D,u){const n=E("Mermaid");return l(),A("div",null,[a[2]||(a[2]=t('<h1 id="pollard-rho" tabindex="-1">Pollard rho <a class="header-anchor" href="#pollard-rho" aria-label="Permalink to &quot;Pollard rho&quot;">​</a></h1><div class="epigraph"><p>伪随机迭代在模 $n$ 上走，Floyd 判圈；$\\gcd(|x-y|,n)$ 给出因子，期望 $\\tilde O(n^{1/4})$ 级。</p><footer>—— 据 Pollard, A Monte Carlo Method for Factorization, 1975；CLRS 第 31.9 节整理</footer></div><p>上一课<a href="/cs/bsgs">BSGS</a>在阶已知的群里根号搜离散对数；本课对象换成合数 \\(n\\)，目标是求非平凡因子。试除要 \\(O(\\sqrt n)\\)，\\(n\\) 上到几十位就不可行。缺口是 Pollard rho：把生日悖论搬到因子 \\(p\\) 的环上找碰撞。<span class="marginnote">生日悖论直觉：一个房间只需约 \\(1.2\\sqrt{365}\\approx 23\\) 人，就有过半概率两人同生日——随机取值之间发生碰撞远比想象快。rho 正是利用这一点：随机迭代约 \\(\\sqrt p\\) 步就可能撞出两个模 \\(p\\) 相同的值，而不是把 \\(p\\) 个值挨个试完。</span>本课不重写 Miller–Rabin 素性；后课 Lucas 换回组合数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n=pq\\) 时，迭代 \\(f(x)=x^2+c\\bmod n\\) 在模 \\(p\\) 的投影里进入一个短环，撞环步数只有 \\(O(\\sqrt p)\\)。我们看不见 \\(p\\)，但 Floyd 龟兔（一个走一步、一个走两步）无需知道环长就能找到模 \\(p\\) 同余的相遇点 \\(x_i\\equiv x_j\\)；此时 \\(\\gcd(|x_i-x_j|,n)\\) 撞出既非 \\(1\\) 也非 \\(n\\) 的因子。期望步数 \\(O(\\sqrt p)\\)，对最小素因子即 \\(O(n^{1/4})\\) 量级；gcd 失败（恰得 \\(n\\)）就换参数 \\(c\\) 重来。</p><p>Brent 变体重排 gcd 时机，省掉大量 \\(f\\) 求值；Pollard \\(p-1\\) 是另一条路（赌 \\(p-1\\) 光滑），点名即可。</p><h3 id="不是素性测试" tabindex="-1">不是素性测试 <a class="header-anchor" href="#不是素性测试" aria-label="Permalink to &quot;不是素性测试&quot;">​</a></h3><p>rho 假定 \\(n\\) 是合数：\\(n\\) 为素数时迭代只在模 \\(n\\) 自身的环上走，gcd 恒为 \\(1\\) 或 \\(n\\)，永远撞不出因子。所以流程是先 Miller–Rabin 确认合数，再跑 rho；不要对素数跑 rho 充当分解。</p><p><span class="marginnote">Pollard 1975。CLRS 31.9。二次筛、NFS 分解大整数，本课 rho 适合 60–80 位因子量级直觉。后课 Lucas 定理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>操作序列：随机选 \\(x_0\\) 与 \\(c\\)；推进 Floyd 循环；每步（或按 Brent 的批量节拍）算一次 gcd；拿到因子 \\(d\\) 后对 \\(d\\) 与 \\(n/d\\) 递归分解。动手前先查完全平方——有平方因子先开方，免得两支相同因子空转。</p>',11)),(l(),d(i,null,{default:o(()=>[s(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22x%E2%86%90x%C2%B2%2Bc%20mod%20n%22%5D%20--%3E%20FLOYD%5B%22%E9%BE%9F%E5%85%94%22%5D%0A%20%20FLOYD%20--%3E%20G%5B%22gcd(%7Cx-y%7C%2C%20n)%22%5D%0A%20%20G%20--%3E%20FAC%5B%22%E9%9D%9E%E5%B9%B3%E5%87%A1%E5%9B%A0%E5%AD%90%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,[r("span",{class:"marginnote"},"龟兔判圈可以想象成两名跑者在同一环形跑道上以一倍速和两倍速起跑：只要跑道是环，快者一定会从后面追上慢者——不需要知道跑道多长，也无需记住谁到过哪里。这就是 Floyd 算法只用两个变量就替代哈希表的原因。")],-1)),a[4]||(a[4]=r("p",null,"离散对数也有 rho 版本，用陪集上的随机函数游走找碰撞，点名即可。",-1)),a[5]||(a[5]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=r("p",null,"机制是生日悖论在模 \\(p\\) 上起作用：\\(O(\\sqrt p)\\) 个值就有相当概率出现一对模 \\(p\\) 同余，碰撞差 \\(x_i-x_j\\) 是 \\(p\\) 的倍数而 \\(n\\) 整体不是——gcd 一筛就是因子。Floyd 的妙处在空间 \\(O(1)\\)：不存历史，用两倍速指针替代哈希表。与 BSGS 对照鲜明：求对数要哈希表存 \\(\\sqrt q\\) 项，分解只需 gcd。rho 每次输出的因子都经 gcd 验证，不会给错答案；Las Vegas 与 Monte Carlo 的严格分类后课再钉。",-1)),(l(),d(i,null,{default:o(()=>[s(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BF%AD%E4%BB%A3%E5%BA%8F%E5%88%97%20xi%20%E6%A8%A1%20n%22%5D%20--%3E%20B%5B%22%E6%8A%95%E5%BD%B1%E5%88%B0%E6%A8%A1%20p%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%A8%A1%20p%20%E5%89%A9%E4%BD%99%E5%8F%AA%E6%9C%89%20p%20%E4%B8%AA%22%5D%0A%20%20C%20--%3E%20D%5B%22%E7%BA%A6%20%E2%88%9Ap%20%E6%AD%A5%E5%90%8E%E5%87%BA%E7%8E%B0%E5%90%8C%E4%BD%99%E5%AF%B9%20xi%20%E2%89%A1%20xj%22%5D%0A%20%20D%20--%3E%20E%5B%22p%20%E6%95%B4%E9%99%A4%20xi%E2%88%92xj%22%5D%0A%20%20E%20--%3E%20F%5B%22n%20%E9%80%9A%E5%B8%B8%E4%B8%8D%E6%95%B4%E9%99%A4%20xi%E2%88%92xj%22%5D%0A%20%20F%20--%3E%20G%5B%22gcd(%7Cxi%E2%88%92xj%7C%2C%20n)%20%3D%20p%22%5D%0A%20%20G%20--%3E%20H%5B%22%E8%8B%A5%E5%BE%97%20n%20%E5%88%99%E6%8D%A2%20c%20%E9%87%8D%E6%9D%A5%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p><span class="marginnote">常见误区：初学者容易以为 gcd 每次都能干净地吐出 \\(p\\)。实际上碰撞可能“撞过头”——好几个不同的模 \\(p\\) 值同时同余，使 \\(p^2\\) 整除差值，gcd 直接给出 \\(n\\)。此时算法并没有错，只需换一个常数 \\(c\\)（或起点 \\(x_0\\)）重新迭代，失败概率约每次一半。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写数域筛 NFS，也不展开 Lenstra 的椭圆曲线分解 ECM；量级边界在 marginnote：rho 适合中等因子，大整数要二次筛与 NFS。后课默认：中等因子用 rho。下一课 Lucas 定理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(f\\) 迭代 + Floyd + gcd 出因子。</li><li>期望依赖最小素因子的根号。</li><li>先确认合数。</li><li>出处：Pollard, 1975；CLRS 第 31.9 节。</li></ul>',5))])}const g=p(h,[["render",B]]);export{f as __pageData,g as default};
